#define BITSHIFT static_cast<int32_t>((sizeof(int32_t) - 1) * 8)
#define REFRESH_MASK                                                        \
    while (num < BITSHIFT) {                                                \
        mask |= static_cast<uint32_t>(this->getByte()) << (BITSHIFT - num); \
        num += 8;                                                           \
        part2remain -= 8;                                                   \
    }

